\[
\min_{0\le k\le T-1}\dualnorm{\nabla f(x_k)}^{2}
\;\le\;
\frac{4L_h}{\eta\,T}\,
\bigl(f(x_0)-f^\star\bigr).
\]
\end{theorem}

