\D{x}{z}-\D{x}{y}-\D{y}{z}
    =\inner{\nabla h(y)-\nabla h(z)}{x-y}.
\tag{7}
\]
\end{lemma}
\begin{proof}
Straightforward expansion of the definition of $D_h$.
\end{proof}

