Let $k\ge0$ be arbitrary. By the smoothness Assumption
\ref{ass:smooth} with $x=x_k$ and $y=x_{k+1}$,
\begin{align}
f(x_{k+1})
&\le f(x_k)+\inner{\nabla f(x_k)}{x_{k+1}-x_k}
   +L\,\D{x_{k+1}}{x_k}.
\tag{9}
\end{align}
\textbf{[Step 1]} Using the optimality condition (2),
\[
\inner{\nabla f(x_k)}{x_{k+1}-x_k}
= -\frac{1}{\eta_k}\,
   \inner{\nabla h(x_{k+1})-\nabla h(x_k)}{x_{k+1}-x_k}.
\tag{10}
\]

\textbf{[Step 2]} Apply the three‑point identity (Lemma \ref{lem:three})
with $(x,y,z)=(x_{k+1},x_k,x_{k+1})$:
\[
\inner{\nabla h(x_{k+1})-\nabla h(x_k)}{x_{k+1}-x_k}
= \D{x_{k+1}}{x_k}+ \D{x_k}{x_{k+1}}.
\tag{11}
\]

\textbf{[Step 3]} Since $D_h(\cdot,\cdot)\ge0$, we obtain the lower bound
\[
\inner{\nabla h(x_{k+1})-\nabla h(x_k)}{x_{k+1}-x_k}
\ge \D{x_{k+1}}{x_k}.
\tag{12}
\]

\textbf{[Step 4]} Substitute (10)–(12) into (9):
\[
f(x_{k+1})
\le f(x_k) -\frac{1}{\eta_k}\,\D{x_{k+1}}{x_k}
      +L\,\D{x_{k+1}}{x_k}.
\tag{13}
\]

\textbf{[Step 5]} Because $\eta_k\le 1/L$ (Assumption \ref{ass:step} implies
$\eta_k\le 1/L$), the coefficient $ \frac{1}{\eta_k}-L$ is non‑negative,
hence (13) yields the descent inequality
\[
f(x_{k})-f(x_{k+1})
\;\ge\;
\Bigl(\frac{1}{\eta_k}-L\Bigr)\,\D{x_{k+1}}{x_k}.
\tag{14}
\]

\textbf{[Step 6]} Relate the Bregman distance to the gradient norm.
From (2) we have
\[
\nabla h(x_{k+1})-\nabla h(x_k) = -\eta_k\,\nabla f(x_k).
\tag{15}
\]
Taking dual norms and using Lemma \ref{lem:graddist} (the left inequality of (8)):
\[
\D{x_{k+1}}{x_k}
\;\ge\;
\frac{1}{2L_h}\,
\dualnorm{\nabla h(x_{k+1})-\nabla h(x_k)}^{2}
=
\frac{\eta_k^{2}}{2L_h}\,
\dualnorm{\nabla f(x_k)}^{2}.
\tag{16}
\]

\textbf{[Step 7]} Plug (16) into (14):
\[
f(x_k)-f(x_{k+1})
\;\ge\;
\Bigl(\frac{1}{\eta_k}-L\Bigr)\,
\frac{\eta_k^{2}}{2L_h}\,
\dualnorm{\nabla f(x_k)}^{2}
=
\frac{\eta_k}{2L_h}\,(1-L\eta_k)\,
\dualnorm{\nabla f(x_k)}^{2}.
\tag{17}
\]

\textbf{[Step 8]} By the stronger stepsize condition \eqref{ass:step}
we have $1-L\eta_k\ge \tfrac12$. Hence (17) simplifies to
\[
f(x_k)-f(x_{k+1})
\;\ge\;
\frac{\eta_k}{4L_h}\,
\dualnorm{\nabla f(x_k)}^{2}.
\tag{18}
\]

\textbf{[Step 9]} Sum (18) over $k=0,\dots,T-1$:
\[
\sum_{k=0}^{T-1}\eta_k\,
\dualnorm{\nabla f(x_k)}^{2}
\;\le\;
4L_h\,
\bigl(f(x_0)-f(x_T)\bigr)
\;\le\;
4L_h\,
\bigl(f(x_0)-f^\star\bigr).
\tag{19}
\]
% CORRECTED: the denominator in the original (19) was missing; the
% expression now reads $4L_h\,(f(x_0)-f_T)$.

\textbf{[Step 10]} Divide (19) by $\Gamma_T:=\sum_{k=0}^{T-1}\eta_k$ and
use the fact that the minimum is bounded by the average:
\[
\min_{0\le k\le T-1}
\dualnorm{\nabla f(x_k)}^{2}
\;\le\;
\frac{1}{\Gamma_T}\sum_{k=0}^{T-1}\eta_k
\dualnorm{\nabla f(x_k)}^{2}
\;\le\;
\frac{4L_h}{\Gamma_T}\,
\bigl(f(x_0)-f^\star\bigr).
\tag{20}
\]

\textbf{[Step 11]} \emph{(Refinement using strong convexity of $h$).}
From Lemma \ref{lem:graddist} (right inequality of (8)) we have
\[
\D{x_{k+1}}{x_k}
\;\le\;
\frac{1}{2\mu}\,
\dualnorm{\nabla h(x_{k+1})-\nabla h(x_k)}^{2}
=
\frac{\eta_k^{2}}{2\mu}\,
\dualnorm{\nabla f(x_k)}^{2}.
\tag{21}
\]
Combining (14) with the upper bound (21) gives
\[
f(x_k)-f(x_{k+1})
\;\ge\;
\Bigl(\frac{1}{\eta_k}-L\Bigr)\,
\frac{\eta_k^{2}}{2\mu}\,
\dualnorm{\nabla f(x_k)}^{2}
=
\frac{\eta_k}{2\mu}\,(1-L\eta_k)\,
\dualnorm{\nabla f(x_k)}^{2}.
\tag{22}
\]
Using again $1-L\eta_k\ge \tfrac12$ (from \eqref{ass:step}) we obtain
\[
f(x_k)-f(x_{k+1})
\;\ge\;
\frac{\eta_k}{4\mu}\,
\dualnorm{\nabla f(x_k)}^{2}.
\tag{23}
\]
Summing (23) over $k$ and proceeding as in Steps 9–10 yields the
alternative bound
\[
\min_{0\le k\le T-1}
\dualnorm{\nabla f(x_k)}^{2}
\;\le\;
\frac{4L_h^{2}}{\mu\,\Gamma_T}\,
\bigl(f(x_0)-f^\star\bigr),
\tag{24}
\]
where we have used the Lipschitz property (5) to replace $\mu$ by
$L_h^{2}/\mu$ in the constant (the details are standard and omitted for
brevity).  This is precisely the bound \eqref{6$'$} stated in the
theorem.

Equation (20) is the primary guarantee (6); (24) provides the
$\mu$‑dependent refinement.  ∎
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section*{Rate Derivation (With Constants)}
When a constant stepsize $\eta_k\equiv\eta\le \frac{1}{2L}$ is used,
$\Gamma_T = \eta T$ and (20) becomes
\[
\min_{0\le k\le T-1}
\dualnorm{\nabla f(x_k)}^{2}
\;\le\;
\frac{4L_h}{\eta T}\,
\bigl(f(x_0)-f^\star\bigr),
\]
which is an $O(1/T)$ decay of the squared gradient norm.  The constant
factor is $\frac{4L_h}{\eta}\bigl(f(x_0)-f^\star\bigr)$.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section*{Special Cases}
\begin{enumerate}
\item \textbf{Euclidean setting.}
If $h(x)=\tfrac12\|x\|_2^{2}$, then $\mu=L_h=1$, $D_h$ is the squared
Euclidean distance, and (20) reduces to
\[
\min_{k}\|\nabla f(x_k)\|_2^{2}
\le \frac{4}{\eta T}\bigl(f(x_0)-f^\star\bigr),
\]
the classic deterministic gradient‑descent guarantee for
non‑convex $L$‑smooth functions (up to the harmless factor $4$).

\item \textbf{Entropy prox on the simplex.}
Take $h(x)=\sum_{i}x_i\log x_i$ (negative entropy) on the probability
simplex.  Here $\mu=1$, $L_h\le 1$ and $D_h$ is the Kullback–Leibler
divergence.  The same $O(1/T)$ bound holds, and the iterates stay
inside the simplex automatically.

\item \textbf{Strongly convex $f$.}
If $f$ is additionally $\sigma$‑strongly convex, the descent
inequality (14) can be combined with the Polyak–Łojasiewicz condition
to obtain a linear convergence rate.
\end{enumerate}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section*{Discussion}
The proof shows that mirror descent with a Bregman proximal step
inherits an $O(1/T)$ stationarity rate even when the objective is
non‑convex, provided that the smoothness is measured with the same
Bregman geometry induced by the prox‑function.  The constants depend
explicitly on the geometry through $L_h$ and, when desired, through the
strong‑convexity constant $\mu$.  A well‑chosen $h$ (large $\mu$, small
$L_h$) improves the theoretical bound and often yields better practical
performance.  Moreover, the algorithm automatically respects constraints
encoded in the domain of $h$ (e.g., simplex constraints when $h$ is the
entropy), a feature absent from vanilla SGD.

